import 'package:flutter/material.dart';import '../auth/auth_notifier.dart';import '../models/app_user.dart';import 'package:go_router/go_router.dart';import 'package:provider/provider.dart';import '../models/book.dart';import '../repositories/api_book_repository.dart';import '../repositories/author_repository.dart';import '../repositories/book_repository.dart';import '../repositories/genre_repository.dart';import '../repositories/publisher_repository.dart';import '../repositories/repository_errors.dart';import '../services/theme_controller.dart';import '../state/book_list_notifier.dart';import '../widgets/theme_button.dart';class BookDetailScreen extends StatefulWidget{final int id;final ThemeController themeController;const BookDetailScreen({super.key,required this.id,required this.themeController});@override State<BookDetailScreen>createState()=>_S();}class _S extends State<BookDetailScreen>{late Future<List<Object?>> future;@override void initState(){super.initState();future=load();}Future<List<Object?>>load()async{final b=await context.read<BookListNotifier>().findById(widget.id);if(b==null)return[null];final ps=await context.read<PublisherRepository>().allActive(),as=await context.read<AuthorRepository>().allActive(),gs=await context.read<GenreRepository>().allActive();return[b,ps.where((e)=>e.id==b.publisherId).map((e)=>e.name).join(),as.where((e)=>b.authorIds.contains(e.id)).map((e)=>e.fullName).join(', '),gs.where((e)=>b.genreIds.contains(e.id)).map((e)=>e.name).join(', ')];}Future<void>issue()async{try{final repo=context.read<BookRepository>();if(repo is ApiBookRepository)await repo.issue(widget.id);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Книга выдана. Количество доступных экземпляров уменьшено.')));setState(()=>future=load());}}on RepositoryConflictException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Конфликт 409: ${e.message}')));}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Карточка книги'),actions:[ThemeButton(controller:widget.themeController)]),body:FutureBuilder<List<Object?>>(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final b=s.data?[0]as Book?;if(b==null)return const Center(child:Text('Книга не найдена'));final p=(s.data?[1]as String?)??'—',a=(s.data?[2]as String?)??'—',g=(s.data?[3]as String?)??'—';return Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:700),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(b.title,style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:16),Text('ISBN: ${b.isbn}'),Text('Издательство: $p'),Text('Авторы: $a'),Text('Жанры: $g'),Text('Доступно: ${b.copiesAvailable}/${b.copiesTotal}'),const SizedBox(height:16),if(c.read<AuthNotifier>().can(Permission.manageLoans))FilledButton.icon(onPressed:issue,icon:const Icon(Icons.outbox_outlined),label:const Text('Выдать экземпляр (проверка 409)')),if(c.read<AuthNotifier>().can(Permission.manageBooks))OutlinedButton.icon(onPressed:()=>c.go('/books/${b.id}/edit'),icon:const Icon(Icons.edit),label:const Text('Редактировать')),TextButton(onPressed:()=>c.pop(),child:const Text('Назад'))])))));}));}
